def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many full water units we likely need to avoid collapse.
    # If supply is high enough, a modest allocation can cover our requirement.
    # We map supply to a target fraction of water coverage.
    # Supply in [15,25] => coverage ratio in [15/9=1.67, 25/9=2.78]
    coverage = supply / float(WATER_REQ)

    # Base bid: aim to secure enough share without matching Cindy's overbids.
    # Scale down when supply is abundant.
    if coverage >= 2.4:
        base = DAILY_SALARY * 0.35
    elif coverage >= 1.9:
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.6

    # If someone previously bid extremely high, they likely chase survival; we slightly increase,
    # but keep well below their extreme to avoid budget burn.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        # Cindy-like behavior: raise only modestly.
        base = max(base, DAILY_SALARY * 0.55)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        base = max(base, DAILY_SALARY * 0.5)

    # Urgency from our hp and no_water_days
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])
    budget = float(my_status['budget'])

    if hp <= 2 or no_water_days >= 2:
        # Must secure water; bid more aggressively but still bounded.
        base = max(base, DAILY_SALARY * 0.8)
    elif hp <= 4 or no_water_days == 1:
        base = max(base, DAILY_SALARY * 0.65)

    # Final cap: never exceed budget.
    bid = min(budget, base)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev_bid = sum(prev_bids) / len(prev_bids)
    max_prev_bid = max(prev_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev_bid + 5.0)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], max_prev_bid * 1.1)

    return min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev_bid * 0.9))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev > 200:
            if hp > 3:
                return min(budget, DAILY_SALARY * 0.3)
            else:
                return min(budget, DAILY_SALARY * 0.8)
        elif highest_prev > DAILY_SALARY:
            return min(budget, max(DAILY_SALARY * 0.4, highest_prev * 0.5))
    if hp <= 2:
        return min(budget, DAILY_SALARY * 0.9)
    if hp <= 4:
        return min(budget, DAILY_SALARY * 0.7)
    base_bid = DAILY_SALARY * 0.5
    # adjust for supply: more supply means lower bid
    num_opponents = len(alive_opponents)
    # ensure int for index if needed
    adjustment = supply / (WATER_REQ * (num_opponents + 1))
    if adjustment > 1.5:
        base_bid = DAILY_SALARY * 0.4
    elif adjustment < 0.8:
        base_bid = DAILY_SALARY * 0.7
    return min(budget, base_bid)
